/* ИЗО (рисование), 1–4 классы. Два вида занятий:
   1) рисование по шагам: ребёнок обводит пунктир пальцем или мышью, игра проверяет точность, в конце можно раскрасить;
   2) вопросы про цвета, линии, фигуры, композицию, жанры и художников (тот же движок, что у математики).
   Холст 640×480, все контуры собираются из простых фигур (круг, овал, линия, ломаная, дуга). */
Object.assign(MTOP, {
  i_line: 'Виды линий', i_shape: 'Фигуры', i_primary: 'Цвета', i_mix: 'Смешивание красок', i_warm: 'Тёплые и холодные цвета', i_tone: 'Оттенки',
  i_tools: 'Материалы и инструменты', i_symm: 'Симметрия', i_compos: 'Композиция и перспектива', i_light: 'Свет и тень', i_genre: 'Жанры живописи', i_artist: 'Художники и картины'
});

/* ---------- фигуры для холста ---------- */
const IZ = {
  pts(f, len) { const n = Math.max(2, Math.ceil(len / 8)), o = []; for (let i = 0; i <= n; i++) o.push(f(i / n)); return o; },
  line(x1, y1, x2, y2) { return IZ.pts(t => [x1 + (x2 - x1) * t, y1 + (y2 - y1) * t], Math.hypot(x2 - x1, y2 - y1)); },
  ell(cx, cy, rx, ry, rot = 0, a0 = 0, a1 = 360) {
    const r = rot * Math.PI / 180, len = Math.PI * (rx + ry) * Math.abs(a1 - a0) / 180;
    return IZ.pts(t => { const a = (a0 + (a1 - a0) * t) * Math.PI / 180, x = rx * Math.cos(a), y = ry * Math.sin(a); return [cx + x * Math.cos(r) - y * Math.sin(r), cy + x * Math.sin(r) + y * Math.cos(r)]; }, len);
  },
  circle(cx, cy, r) { return IZ.ell(cx, cy, r, r); },
  arc(cx, cy, rx, ry, a0, a1) { return IZ.ell(cx, cy, rx, ry, 0, a0, a1); },
  poly(p, closed = true) { const q = closed ? p.concat([p[0]]) : p; let o = []; for (let i = 0; i < q.length - 1; i++) o = o.concat(IZ.line(q[i][0], q[i][1], q[i + 1][0], q[i + 1][1])); return o; },
  rect(x, y, w, h) { return IZ.poly([[x, y], [x + w, y], [x + w, y + h], [x, y + h]]); },
  wave(x1, y, x2, amp, n) { return IZ.pts(t => [x1 + (x2 - x1) * t, y - amp * Math.sin(t * n * 2 * Math.PI)], (x2 - x1) * 1.3); },
  zig(x1, y, x2, amp, n) { const p = []; for (let i = 0; i <= n; i++) p.push([x1 + (x2 - x1) * i / n, y + (i % 2 ? amp : -amp)]); return IZ.poly(p, false); },
  spiral(cx, cy, r, turns) { return IZ.pts(t => [cx + r * t * Math.cos(t * turns * 2 * Math.PI), cy + r * t * Math.sin(t * turns * 2 * Math.PI)], r * turns * 3.2); },
  star(cx, cy, r1, r2, n = 5) { const p = []; for (let i = 0; i < n * 2; i++) { const a = -Math.PI / 2 + i * Math.PI / n, r = i % 2 ? r2 : r1; p.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]); } return IZ.poly(p); },
  heart(cx, cy, s) { return IZ.pts(t => { const a = t * 2 * Math.PI; return [cx + s * 16 * Math.pow(Math.sin(a), 3), cy - s * (13 * Math.cos(a) - 5 * Math.cos(2 * a) - 2 * Math.cos(3 * a) - Math.cos(4 * a))]; }, s * 120); },
  rays(cx, cy, r1, r2, n) { return Array.from({ length: n }, (_, i) => { const a = i * 2 * Math.PI / n; return IZ.line(cx + r1 * Math.cos(a), cy + r1 * Math.sin(a), cx + r2 * Math.cos(a), cy + r2 * Math.sin(a)); }); },
  petals(cx, cy, n, d, rx, ry) { return Array.from({ length: n }, (_, i) => { const a = i * 360 / n; return IZ.ell(cx + d * Math.cos(a * Math.PI / 180), cy + d * Math.sin(a * Math.PI / 180), rx, ry, a); }); }
};
const { line: ZL, circle: ZC, ell: ZE, arc: ZA, poly: ZP, rect: ZR } = IZ;

